Bash(powershell -NoProfile -Command '
Add-Type -AssemblyName System.Drawing
$img = [System.Drawing.Image]::FromFile\("C:\\Users\\JUNGLE\\.qoder\\tmp\\hexa_right_zoom.png"\)
$bmp = New-Object System.Drawing.Bitmap\($img\)
$minX = $bmp.Width; $maxX = -1; $minY = $bmp.Height; $maxY = -1
for \($y = 0; $y -lt $bmp.Height; $y++\) {
  for \($x = 0; $x -lt $bmp.Width; $x++\) {
    $c = $bmp.GetPixel\($x, $y\)
    if \($c.R -ge 90 -and $c.R -le 190 -and $c.G -lt 45 -and $c.B -lt 70\) {
      if \($x -lt $minX\) { $minX = $x }; if \($x -gt $maxX\) { $maxX = $x }
      if \($y -lt $minY\) { $minY = $y }; if \($y -gt $maxY\) { $maxY = $y }
    }
  }
}
Write-Output "size=$\($bmp.Width\)x$\($bmp.Height\) bounds x=$minX..$maxX y=$minY..$maxY"
$cy = [int]\(\($minY + $maxY\) / 2\)
$runs = @\(\); $inRun = $false; $start = 0
for \($x = 0; $x -lt $bmp.Width; $x++\) {
  $c = $bmp.GetPixel\($x, $cy\)
  $hit = $c.R -ge 90 -and $c.R -le 190 -and $c.G -lt 45 -and $c.B -lt 70
  if \($hit -and -not $inRun\) { $inRun = $true; $start = $x }
  if \(-not $hit -and $inRun\) { $inRun = $false; $runs += "$start..$\($x-1\)\($\($x-$start\)\)" }
}
if \($inRun\) { $runs += "$start..$\($bmp.Width-1\)" }
Write-Output "center row y=$cy runs: $\($runs -join ", "\)"
$cx = [int]\(\($minX + $maxX\) / 2\)
$runs = @\(\); $inRun = $false; $start = 0
for \($y = 0; $y -lt $bmp.Height; $y++\) {
  $c = $bmp.GetPixel\($cx, $y\)
  $hit = $c.R -ge 90 -and $c.R -le 190 -and $c.G -lt 45 -and $c.B -lt 70
  if \($hit -and -not $inRun\) { $inRun = $true; $start = $y }
  if \(-not $hit -and $inRun\) { $inRun = $false; $runs += "$start..$\($y-1\)\($\($y-$start\)\)" }
}
if \($inRun\) { $runs += "$start..$\($bmp.Height-1\)" }
Write-Output "center col x=$cx runs: $\($runs -join ", "\)"
$bmp.Dispose\(\); $img.Dispose\(\)
')

